window.__BUNDLE__={"generatedAt":"2026-09-10T11:48:19.904765+00:00","recentDays":7,"archiveDays":1825,"recentCutoff":"2026-09-03","archiveCutoff":"2021-09-11","addedToday":0,"addedThisRun":0,"fetchStats":{"hf":233,"arxiv":1365,"total":1598},"freshness":{"latestPaperDate":"2026-09-10","latestPublishedDate":"2026-09-10","latestBatchCount":226,"newInLast24h":264,"newInLast48h":1018},"historyTotal":12867,"topicCounts":{"Multi-Agent":1970,"Evaluation":6812,"Planning":1046,"Memory":276,"Code Agent":575,"Interpretability":467,"Agentic RAG":1086,"Agentic Search":1348,"RL for LLM":857,"Reasoning":3813,"Hallucination":753,"Post-Training":1629,"Alignment":1787,"World Model":166,"Tool Use":1097,"Agent Safety":2122,"Computer Use":231,"Reflection":490,"VLM Training":770,"LLM Training":1454,"Fine-tuning":1886,"Multimodal Agent":77,"Agent Framework":696,"Error Attribution":100,"Data Engine":275},"count":36,"recentTotal":1809,"archiveCount":0,"archiveTotal":11058,"sources":{"hf":54,"arxiv":1755,"semanticScholar":0},"archiveSources":{"hf":0,"arxiv":0,"semanticScholar":0},"warnings":[],"notes":["archive is split by year under data/archive/ for fast lazy loading; data/history.json keeps the complete database"],"papers":[{"id":"arxiv:2609.10522","authors":["Yanzhe Chen","Zechen Bai","Zhijun Cao","Wenzheng Zeng","Kevin Qinghong Lin","Yiqi Lin","Guoqiang Liang","Kevin Yuchen Ma","Qiming Huang","Mike Zheng Shou"],"tags":["LLM Training","VLM Training","Fine-tuning"],"date":"2026-09-10","arxiv":"https://arxiv.org/abs/2609.10522","title":"Show-Harness: Just a VLM Agent Can Play Robots","url":"https://arxiv.org/abs/2609.10522","hfUrl":"https://huggingface.co/papers/2609.10522","source":"hf","topics":["LLM Training","VLM Training","Fine-tuning"],"upvotes":50,"pdf":"https://arxiv.org/pdf/2609.10522.pdf","submittedDate":"2026-09-09","announceDate":"2026-09-10","abstract":"Foundation vision-language models (VLMs) exhibit broad intelligence about the world, yet translating this intelligence into robot control remains challenging. We present Show-Harness, an Embodied Harness that enables VLMs to \"play\" robots through a compact semantic interface linking intent to action. Show-Harness exposes discrete semantic action units that VLMs can naturally reason over, while embodiment-specific interpreters deterministically ground them into local robot actions, keeping the VLM directly responsible for fine-grained physical decisions. Through the same interface, Show-Harness demonstrates the feasibility of (1) directly unlocking closed-source frontier VLMs for zero-shot robot control, and (2) adapting small-scale open-source VLMs for low-cost deployment with just a few GPU-hours of fine-tuning. We further develop GUMI (GUI Manipulation Interface), which extends the sam"},{"id":"arxiv:2609.10540","authors":["Zheng-Hui Huang","Guixu Lin","Jiacheng Lin","Yi-Chuan Huang","Ruihan Yu","Muyao Niu","Siqi Yang","Yu-Lun Liu","Yung-Yu Chuang","Kaipeng Zhang","Zhixiang Wang"],"tags":["Evaluation","World Model"],"date":"2026-09-10","arxiv":"https://arxiv.org/abs/2609.10540","title":"Programmable World Model","url":"https://arxiv.org/abs/2609.10540","hfUrl":"https://huggingface.co/papers/2609.10540","source":"hf","topics":["Evaluation","World Model"],"upvotes":39,"pdf":"https://arxiv.org/pdf/2609.10540.pdf","submittedDate":"2026-09-09","announceDate":"2026-09-10","abstract":"Recent video world models generate increasingly realistic and interactive visual experiences, yet lack reliable mechanisms for maintaining persistent world state and enforcing programmable rules over extended interactions. We introduce Programmable World Model, a framework that decouples world-state evolution from visual observation generation. An agent translates natural-language instructions into executable programs that specify entity states and state-transition rules, enabling direct control over individual entities and their interactions. A lightweight engine executes these programs to update and maintain an explicit, persistent global world state, including off-screen entities and non-visual attributes. To connect world state with visual generation, we introduce state-augmented 3D oriented bounding boxes (OBBs) as an intermediate representation. This representation, together with t"},{"id":"arxiv:2609.09219","authors":["Jingjie Ning","Shanshan Zhong","Xiaochuan Li","Ji Zeng"],"tags":["Agentic Search","Evaluation"],"date":"2026-09-10","arxiv":"https://arxiv.org/abs/2609.09219","title":"Scores Alone Do Not Prove Discovery: The Discovery Certification Protocol for Auditing AI Research Agents","url":"https://arxiv.org/abs/2609.09219","hfUrl":"https://huggingface.co/papers/2609.09219","source":"hf","topics":["Agentic Search","Evaluation"],"upvotes":13,"pdf":"https://arxiv.org/pdf/2609.09219.pdf","submittedDate":"2026-09-07","announceDate":"2026-09-10","abstract":"AI research agents combine prior knowledge, public sources, and experimental feedback to produce useful results. The Discovery Certification Protocol (DCP) turns claims about these results into executable recovery and feedback tests. Gate 1 validates useful improvement on sealed evaluation. Gate 2 gives matched agents the registered starting information and observed Web content while withholding the target research history. Every valid method reaching the numerical target supplies a recovery witness and triggers the Core veto. DCP Core requires adequate controls, zero observed recoveries, and a finite-sample bound on recovery in one fresh registered episode. Optional Gate 3 measures the average effect of truthful feedback relative to a specified neutral policy from a shared checkpoint. DCP Evidence adds this effect after independent null calibration and a registered effect margin. Two co"},{"id":"arxiv:2609.10226","authors":["Leilei Ding","Shumin Wang","Yuting Huang","Fanqi Wan","Yinmin Zhang","Qi Han","Yiming Xu","Feiyuan Zhang","Xiaomeng Chu","Guoliang You","Wuyang Zhang","Daxin Jiang","Yanyong Zhang"],"tags":["Reasoning","Evaluation"],"date":"2026-09-10","arxiv":"https://arxiv.org/abs/2609.10226","title":"$Φ$-Bench: Can Large Language Models Engineer the Infrastructure That Powers Them?","url":"https://arxiv.org/abs/2609.10226","hfUrl":"https://huggingface.co/papers/2609.10226","source":"hf","topics":["Reasoning","Evaluation"],"upvotes":5,"pdf":"https://arxiv.org/pdf/2609.10226.pdf","submittedDate":"2026-09-09","announceDate":"2026-09-10","abstract":"Large language models (LLMs) have demonstrated remarkable capabilities in reasoning and code generation, raising the prospect that they could assist in developing and optimizing the very infrastructure that powers them. However, existing benchmarks mainly focus on isolated kernels, predefined operators, or pre-specified optimization targets, and therefore fail to evaluate the ability of LLMs to perform open-ended, long-horizon LLM infrastructure engineering. To address this gap, we present $Φ$-Bench, a benchmark for systematically evaluating LLMs on engineering the LLM infrastructure stack. Derived from optimization problems studied in frontier research and grounded in real-world code repositories, $Φ$-Bench provides broad coverage of the LLM infrastructure stack and spans tasks of varying complexity, ranging from localized kernel-level function completion to long-horizon implementation "},{"id":"arxiv:2609.09187","authors":["Xingyuan Bu","Chengru Song","Hao Zhou","Tao Zhou","Dong Li","Wei Li","Shilong Li","Hao Shi","Yongxin Guo","Donghao Zhou","Qiangpeng Yang","Shilei Wen"],"tags":["Post-Training","LLM Training","Reasoning"],"date":"2026-09-10","arxiv":"https://arxiv.org/abs/2609.09187","title":"AgenticGen: Reward-Guided Agentic Video Generation for Advertising","url":"https://arxiv.org/abs/2609.09187","hfUrl":"https://huggingface.co/papers/2609.09187","source":"hf","topics":["Post-Training","LLM Training","Reasoning"],"upvotes":3,"pdf":"https://arxiv.org/pdf/2609.09187.pdf","submittedDate":"2026-08-31","announceDate":"2026-09-10","abstract":"Advertising video generation is not only a video synthesis task, but also a product-conditioned reasoning problem whose success is measured by online business metrics. Recent video foundation models can generate realistic clips from multimodal conditions, yet they do not optimize how a product should be transformed into an effective advertisement or how future generation should be improved from online business feedback. To close this loop, we propose AgenticGen, a reward-guided agentic framework that decomposes advertising video generation into two trainable reasoning stages, strategy selection and draft generation, thereby exposing optimization targets that online business feedback can supervise. AgenticGen learns a performance-based reward from accumulated online feedback and a complementary rubric-based reward aligned with human quality standards, then uses them to supervise policy op"},{"id":"arxiv:2609.09657","authors":["Haichuan Hu","Yang Xiao","Mingni Tang","Jiawen Duan","Quanjun Zhang","Congqing He","Hao Zhang","Jiashuo Wang","Johan F. Hoorn","Wenjie Li"],"tags":["Evaluation"],"date":"2026-09-10","arxiv":"https://arxiv.org/abs/2609.09657","title":"RESCUE-BENCH: Towards Relation-Aware Multi-Party Emotional Support Conversation Systems","url":"https://arxiv.org/abs/2609.09657","hfUrl":"https://huggingface.co/papers/2609.09657","source":"hf","topics":["Evaluation"],"upvotes":2,"pdf":"https://arxiv.org/pdf/2609.09657.pdf","submittedDate":"2026-09-09","announceDate":"2026-09-10","abstract":"Existing emotional support conversation systems mainly focus on one-on-one seeker-supporter interactions and individual emotional states, leaving interpersonal relations in multi-party scenarios underexplored. In this work, we introduce relation-aware emotional support conversation, a new task that evaluates whether LLMs can capture and utilize the evolving dynamics of relationships to offer more effective emotional support. We construct RESCUE (Relation-aware Emotional Support Conversation Understanding and Evaluation Benchmark) from real couple and family interview conversations, containing 191 samples, 7,079 annotated turns, and 1,064.8 minutes of video. Based on rich annotations of socio-emotional and support-related dynamics, RESCUE defines six tasks that evaluate two core capabilities required for relation-aware emotional support: Relational Understanding and Relation-Sensitive Sup"},{"id":"arxiv:2609.10355","authors":["Killian Steunou","Yannis Tevissen","Mounîm A. El Yacoubi"],"tags":["Evaluation"],"date":"2026-09-10","arxiv":"https://arxiv.org/abs/2609.10355","title":"Why Is Video Still So Expensive? A Survey of Inference-Efficiency Mechanisms in Video and Audiovisual LLMs","url":"https://arxiv.org/abs/2609.10355","hfUrl":"https://huggingface.co/papers/2609.10355","source":"arxiv","topics":["Evaluation"],"upvotes":3,"pdf":"https://arxiv.org/pdf/2609.10355.pdf","submittedDate":"2026-09-09","announceDate":"2026-09-10","abstract":"Video understanding has rapidly evolved toward video large language models (VideoLLMs): systems that couple video representations with pretrained large language models and condition generation on a textual prompt. Their strong performance on captioning, question answering, retrieval and temporal grounding comes at a computation and memory cost that grows with frame count and context length, limiting deployment in real-time, mobile and resource-constrained settings. This survey covers inference-efficiency mechanisms for visual and audiovisual VideoLLMs that report concrete reductions in parameter count, FLOPs per input, latency, memory, or visual and audio token count. We analyze bottlenecks across frame sampling, modality encoding, connector-level token reduction, and LLM prefilling and decoding. We organize methods by the pipeline stage at which they act, covering VideoLLMs developed si"},{"id":"arxiv:2609.09875","authors":["Shrey Nag","Sachita","Abhishek Kumar Singh","Lipi Goel","Rajeshwar Singh Janwar"],"tags":["Agent Safety","Error Attribution","Reasoning","Planning","Hallucination"],"date":"2026-09-10","arxiv":"https://arxiv.org/abs/2609.09875","title":"AgentAudit: An Open, Extensible Framework for Full-Lifecycle Trust Evaluation of AI Agents","url":"https://arxiv.org/abs/2609.09875","source":"arxiv","topics":["Agent Safety","Error Attribution","Reasoning","Planning","Hallucination","Evaluation","Alignment"],"upvotes":0,"pdf":"https://arxiv.org/pdf/2609.09875.pdf","submittedDate":"2026-09-09","announceDate":"2026-09-10","abstract":"Existing evaluation frameworks mostly assess only one part of AI agents, such as task completion (AgentBench) or security robustness (AgentDojo, ASB), rather than the complete pipeline of planning, tool selection, tool execution, memory and reasoning. Failures can occur at any stage, yet existing benchmarks rarely identify their precise source. AgentAudit evaluates the entire execution trace across ten capability, grounding, security and behavioural dimensions, namely instruction integrity, planner, memory, tool selection, tool invocation, tool correctness, alignment, tool faithfulness, security and execution integrity, combined with behavioural classification and failure attribution to pinpoint the exact stage responsible for an observed failure. AgentAudit can evaluate any LLM-based AI agent, since it attaches to the agent instead of replacing it. It reads only the recorded execution t"},{"id":"arxiv:2609.10430","authors":["Kostia Kudriavtsev","Parvez Rafi","Sha Sundaram"],"tags":["Agentic RAG","Agentic Search","Multi-Agent","Reasoning","Evaluation"],"date":"2026-09-10","arxiv":"https://arxiv.org/abs/2609.10430","title":"Glyph: A Multi-Strategy Agentic System for Column Description and Sensitivity-Ontology Tagging of Enterprise Data Catalogs","url":"https://arxiv.org/abs/2609.10430","source":"arxiv","topics":["Agentic RAG","Agentic Search","Multi-Agent","Reasoning","Evaluation","Fine-tuning"],"upvotes":0,"pdf":"https://arxiv.org/pdf/2609.10430.pdf","submittedDate":"2026-09-09","announceDate":"2026-09-10","abstract":"Enterprise data lakes accumulate tables faster than human stewards can document or classify them, leaving columns with missing descriptions and unassigned governance labels. This documentation debt undermines data discovery, access control, and regulatory compliance. We present Glyph, a production system that frames two coupled problems, column description generation and column type annotation for data classification, as cooperating LLM agents orchestrated as stateful graphs. The Descriptor grounds generation in the pipeline source code that produces each column, retrieved on demand from an enterprise GitHub via a reasoning--acting tool loop (active Retrieval-Augmented Generation). The Tagger assigns labels from a governed 275-leaf Data Classification Ontology by running three complementary strategies in parallel (a description tagger, a line-of-business regex tagger, and a metadata tagg"},{"id":"arxiv:2609.10315","authors":["Rui Sun","Zhan Shi","Bing He"],"tags":["Error Attribution","LLM Training","Reasoning","Fine-tuning","RL for LLM"],"date":"2026-09-10","arxiv":"https://arxiv.org/abs/2609.10315","title":"TRACE: Training Reasoning Agents for Causal Exploration with Synthesized Rewards","url":"https://arxiv.org/abs/2609.10315","source":"arxiv","topics":["Error Attribution","LLM Training","Reasoning","Fine-tuning","RL for LLM"],"upvotes":0,"pdf":"https://arxiv.org/pdf/2609.10315.pdf","submittedDate":"2026-09-09","announceDate":"2026-09-10","abstract":"Reinforcement learning with verifiable rewards (RLVR) has advanced language-model reasoning in domains such as mathematics and code, where objective answers are inexpensive to check. Diagnostic reasoning over complex data lacks this advantage: establishing the true cause of an anomaly often requires costly expert investigation and may remain ambiguous after the fact. We ask whether this asymmetry of verification can instead be engineered. We sample an intervention, inject it into a controlled simulator, and generate the observations it would produce. The hidden intervention provides an oracle label and objective reward, while the agent must still investigate noisy, confounded, and distributed evidence. We instantiate this approach in TRACE, a digital-advertising diagnostic environment with 12 root causes and fine-grained segment attribution. Agents investigate each episode using Python a"},{"id":"arxiv:2609.09953","authors":["Guillem Ramírez"],"tags":["Post-Training","Hallucination","Evaluation","Alignment","Fine-tuning"],"date":"2026-09-10","arxiv":"https://arxiv.org/abs/2609.09953","title":"Improving Cross-Lingual Token Representations by Adding a Pinch of SALT","url":"https://arxiv.org/abs/2609.09953","source":"arxiv","topics":["Post-Training","Hallucination","Evaluation","Alignment","Fine-tuning"],"upvotes":0,"pdf":"https://arxiv.org/pdf/2609.09953.pdf","submittedDate":"2026-09-09","announceDate":"2026-09-10","abstract":"Cross-lingual sentence encoders enable scalable transfer across hundreds of languages, powering applications such as translation mining and zero-shot learning in low-resource settings. Although trained for sentence-level alignment, they are increasingly also applied to token-level tasks such as hallucination detection and sequence tagging, exposing a mismatch between training and usage. We propose SALT, a lightweight post-training method that improves token representations by injecting span-level supervision into existing sentence encoders. Across five multilingual token-level benchmarks, SALT achieves the best overall results on four of them, outperforming alternative fine-tuning strategies and competitive encoders. It also improves sentence-level performance on cross-lingual retrieval and classification tasks. These results demonstrate that span-level supervision is an effective signal"},{"id":"arxiv:2609.09776","authors":["Eshwar Reddy M","Sourav Karmakar"],"tags":["Post-Training","Reasoning","Evaluation","RL for LLM","World Model"],"date":"2026-09-10","arxiv":"https://arxiv.org/abs/2609.09776","title":"Proof-Carrying Cognition: Closing the Verification Gap with Reality-Settled Reward","url":"https://arxiv.org/abs/2609.09776","source":"arxiv","topics":["Post-Training","Reasoning","Evaluation","RL for LLM","World Model"],"upvotes":0,"pdf":"https://arxiv.org/pdf/2609.09776.pdf","submittedDate":"2026-09-09","announceDate":"2026-09-10","abstract":"Frontier gains in language-model reasoning come from reinforcement learning on reasoning traces and are concentrated in domains with a cheap, sound verifier. We argue the field's binding constraint is the verification gap: no scalable, incorruptible reward for reasoning outside formal domains. We make four contributions. (1) Theory: in a joint-Gaussian model of best-of-N selection, verifier-gold correlation rho is the exact exchange rate between test-time compute and capability, and an unsound verifier pays a polynomial penalty N^(1/rho^2); a margin-free copula form predicts realized soundness of real LLM judges to 4% median error. (2) Demonstration: in program-synthesis testbeds with executable ground truth, including a pre-registered scaled replication, unsound verifiers lose Soundness-under-Pressure as optimization grows (0.94 to 0.32 at N=4096) while a sound verifier improves monoton"},{"id":"arxiv:2609.10333","authors":["Xuan Cuong Ngo","Ngan Le"],"tags":["LLM Training","VLM Training","Evaluation","Alignment","Fine-tuning"],"date":"2026-09-10","arxiv":"https://arxiv.org/abs/2609.10333","title":"Learning to Adapt and Calibrate: Score Distribution Alignment for Few-Shot Uncertainty Prediction in Medical VLMs","url":"https://arxiv.org/abs/2609.10333","source":"arxiv","topics":["LLM Training","VLM Training","Evaluation","Alignment","Fine-tuning"],"upvotes":0,"pdf":"https://arxiv.org/pdf/2609.10333.pdf","submittedDate":"2026-09-09","announceDate":"2026-09-10","abstract":"Uncertainty estimation for medical vision--language models (VLMs) using conformal prediction has gained increasing attention due to its distribution-free coverage guarantees. However, standard conformal prediction relies on exchangeability between calibration and test data and typically requires a sufficiently large calibration set to obtain reliable coverage. These assumptions are difficult to satisfy in few-shot transfer settings, where only a small labeled support set is available to adapt a pretrained VLM to a new medical task, while an unlabeled query set is used for evaluation. Supervised fine-tuning on the support set changes the model parameters and consequently shifts the nonconformity score distribution, breaking exchangeability between calibration and query samples and leading to unreliable coverage under distribution shift. Existing transductive conformal adaptation methods o"},{"id":"arxiv:2609.09664","authors":["Hyojeong Yu","Hyukhun Koh","Minsung Kim","Yunah Jang","Kyomin Jung"],"tags":["Reasoning","Planning","Evaluation","Alignment"],"date":"2026-09-10","arxiv":"https://arxiv.org/abs/2609.09664","title":"PRAGMA: Evaluating Personalized Guidance with Memory Alignment in Lifelong Conversations","url":"https://arxiv.org/abs/2609.09664","source":"arxiv","topics":["Reasoning","Planning","Evaluation","Alignment"],"upvotes":0,"pdf":"https://arxiv.org/pdf/2609.09664.pdf","submittedDate":"2026-09-09","announceDate":"2026-09-10","abstract":"Large language models (LLMs) are increasingly deployed as personalized assistants that interact with users over extended periods of time. As conversations grow longer, relying on full interaction histories becomes increasingly inefficient and unreliable: long contexts introduce substantial computational overhead, making it difficult for models to consistently identify and utilize the most relevant information for the current request. These challenges have motivated memory systems that structure and retrieve user-specific information. In realistic interactions, users often seek practical guidance such as recommendations, planning, and decision support. Unlike factual recall tasks, personalized guidance requires models to integrate information across multiple past conversations and reason about changing user preferences and experiences. However, existing conversational memory evaluations m"},{"id":"arxiv:2609.10239","authors":["Daniel Alejandro Coll Tejeda","Pedro García López","Daniel Barcelona-Pons"],"tags":["Agentic RAG","Agentic Search","Reasoning","Evaluation"],"date":"2026-09-10","arxiv":"https://arxiv.org/abs/2609.10239","title":"LiteRAG: Cost-Efficient Graph-Based Retrieval-Augmented Generation","url":"https://arxiv.org/abs/2609.10239","source":"arxiv","topics":["Agentic RAG","Agentic Search","Reasoning","Evaluation"],"upvotes":0,"pdf":"https://arxiv.org/pdf/2609.10239.pdf","submittedDate":"2026-09-09","announceDate":"2026-09-10","abstract":"Graph-based retrieval can improve multi-hop question answering, but existing approaches often incur high query-time costs and produce diffuse, oversized contexts that reduce generation efficiency. We present LiteRAG, a graph-based retrieval method that replaces expensive retrieval-time LLM control with query-conditioned algorithmic exploration and reasoning-chain context construction. On DistComp, a benchmark for multi-hop retrieval over distributed-systems papers, LiteRAG attains the highest overall quality among the evaluated methods (0.798) while reducing per-query latency by over 100$\\times$ and cost by over 99% relative to GraphRAG Global and DRIFT. On UltraDomain, it matches LinearRAG on overall quality while using about 14$\\times$ fewer tokens. An ablation study indicates that LiteRAG's query-adaptive thresholding and community-aware hub penalization are the main drivers of its to"},{"id":"arxiv:2609.09707","authors":["Yaning Jia","Chunhui Zhang","Wenxuan Xu","Xingjian Diao","Xiaoyuan Wang","Soroush Vosoughi"],"tags":["LLM Training","Reasoning","Evaluation","Fine-tuning"],"date":"2026-09-10","arxiv":"https://arxiv.org/abs/2609.09707","title":"Which Tokens Should SFT Actually Learn? A Token-Trimming Perspective on Mathematical Reasoning","url":"https://arxiv.org/abs/2609.09707","source":"arxiv","topics":["LLM Training","Reasoning","Evaluation","Fine-tuning"],"upvotes":0,"pdf":"https://arxiv.org/pdf/2609.09707.pdf","submittedDate":"2026-09-09","announceDate":"2026-09-10","abstract":"Supervised fine-tuning (SFT) applies a uniform cross-entropy loss to all target tokens, even though different tokens provide unequal learning signals for mathematical reasoning. This uniform treatment can over-sharpen already mastered tokens while amplifying learning pressure on uncertain, low-confidence tokens, leading to suboptimal training dynamics. We propose Trimmed Logit-Gap SFT (TrimSFT), a simple token-level reweighting method that scales the SFT loss according to the logit gap between the gold token and its strongest competitor. TrimSFT trims supervision away from both extremes: tokens already mastered (large logit gap) and tokens weakly supported by the current model (small or negative logit gap), concentrating learning within an intermediate logit-gap region between them. We instantiate this principle with a Gaussian weight centered at margin m with bandwidth τ, requiring no r"},{"id":"arxiv:2609.09647","authors":["Divyanshu Kumar","Nitin Aravind Birur","Tanay Baswa","Sahil Agarwal","Prashanth Harshangi"],"tags":["Agent Safety","Multi-Agent","Evaluation","Agent Framework"],"date":"2026-09-10","arxiv":"https://arxiv.org/abs/2609.09647","title":"Black-Box Red Teaming of Agentic AI: A Taxonomy-Driven Framework for Automated Risk Discovery","url":"https://arxiv.org/abs/2609.09647","source":"arxiv","topics":["Agent Safety","Multi-Agent","Evaluation","Agent Framework"],"upvotes":0,"pdf":"https://arxiv.org/pdf/2609.09647.pdf","submittedDate":"2026-09-09","announceDate":"2026-09-10","abstract":"Agentic systems are rapidly moving to production, where they read untrusted inputs, call tools with real permissions, and act autonomously, expanding the security surface beyond chat-only models. Yet standard evaluations remain single-turn and fail to capture multi-step agent vulnerabilities. We present a systematic black-box framework for risk-aware agent evaluation requiring only basic system descriptions. Our approach introduces: (1) a seven-domain taxonomy mapping observable behaviors to risk categories, (2) fully automated SAGE-RT red teaming producing 120 adversarial scenarios per domain, and (3) human-validated evaluation using LLM judges. Empirical validation across two agent architectures (CrewAI and AutoGen) with four base models reveals alarming patterns: 56.25\\% average governance risk, 65\\% privacy risk in multi-agent configurations, and agent behavior vulnerabilities reachi"},{"id":"arxiv:2609.09578","authors":["Wentao Zhang","Jingyuan Wang","Zetong Zhou","Yifan Yang","Wenrui Wang"],"tags":["Planning","Evaluation","RL for LLM","Agent Framework"],"date":"2026-09-10","arxiv":"https://arxiv.org/abs/2609.09578","title":"CityPlanner: A Sandbox Agent for Executable Urban Planning","url":"https://arxiv.org/abs/2609.09578","source":"arxiv","topics":["Planning","Evaluation","RL for LLM","Agent Framework"],"upvotes":0,"pdf":"https://arxiv.org/pdf/2609.09578.pdf","submittedDate":"2026-09-09","announceDate":"2026-09-10","abstract":"Urban planning is a real-world spatial optimization problem that requires selecting feasible actions from large candidate spaces under practical objectives such as cost and service quality. Existing optimization and reinforcement learning methods are effective for fixed formulations, but often depend on task-specific representations and constraint handling. We propose \\emph{CityPlanner}, a sandbox-agent framework for executable urban planning. CityPlanner introduces \\emph{UrbanSandbox}, a unified file-based environment where agents inspect task files, generate plans, run evaluators, and revise decisions based on executable feedback. To make learning tractable, we further propose atomic-task reinforcement learning, which decomposes long sandbox trajectories into \\emph{BuildPlan} for initial construction and \\emph{ImprovePlan} for feedback-based refinement. Experiments on a real-world benc"},{"id":"arxiv:2609.09768","authors":["Fumihiko Tachibana","Daisuke Miyashita","Jun Deguchi"],"tags":["Agentic RAG","Agentic Search","Evaluation","Fine-tuning"],"date":"2026-09-10","arxiv":"https://arxiv.org/abs/2609.09768","title":"Fine-Tuning a KV Cache Concatenation-Aware Model or Recomputing KV Caches? Why Not Both?","url":"https://arxiv.org/abs/2609.09768","source":"arxiv","topics":["Agentic RAG","Agentic Search","Evaluation","Fine-tuning"],"upvotes":0,"pdf":"https://arxiv.org/pdf/2609.09768.pdf","submittedDate":"2026-09-09","announceDate":"2026-09-10","abstract":"In Retrieval-Augmented Generation (RAG) systems, a large number of retrieved chunks are concatenated to form the input context so that users can receive high-quality responses based on external knowledge. As a result, the input context length increases substantially, leading to a larger prefill workload and, in turn, a longer time to first token (TTFT). While previous works that reuse precomputed key-value (KV) caches effectively reduce TTFT for long-context inputs, it remains unclear whether response quality is preserved when the input context becomes very long. In this paper, we propose a combined approach that (i) fine-tunes the model while taking KV cache concatenation into account and (ii) selectively recomputes a subset of the KV caches. By applying both techniques, we demonstrate improved accuracy for long-context inputs. Experiments on the RULER benchmark show that, for a 124k-to"},{"id":"arxiv:2609.10155","authors":["Christoph Wigbels","Ali Abusaleh","Markus T. Jansen","Alexander Mehler","Markus J. Hofmann"],"tags":["Agentic RAG","Agentic Search","Alignment","Fine-tuning"],"date":"2026-09-10","arxiv":"https://arxiv.org/abs/2609.10155","title":"From Retrieval to Weights: Parametric Individualization of Small Language Models with Individual Text Corpora","url":"https://arxiv.org/abs/2609.10155","source":"arxiv","topics":["Agentic RAG","Agentic Search","Alignment","Fine-tuning"],"upvotes":0,"pdf":"https://arxiv.org/pdf/2609.10155.pdf","submittedDate":"2026-09-09","announceDate":"2026-09-10","abstract":"We approach a cognitive simulation perspective on episodic and semantic memory in multiple-choice question answering by incorporating text from individual text corpora (ITC) into retrieval-augmented generation and DoRA fine-tuning. We web-crawl the search histories of 515 participants who answered 36 multiple-choice knowledge items and analyze a stratified subsample of 150 participants. For each participant, one DoRA adapter consolidates their ITC into a small language model (SLM) whose baseline correctness falls below the participants' lowest quartile. The adapter measurably writes the ITC into the weights: it fits its own participant's held-out text better than other participants' texts (dz =1.27), an individuality effect that increases with ITC size in rank order. On the generalized knowledge test, however, the adapter adds knowledge rather than alignment with the individual: log-loss"},{"id":"arxiv:2609.10266","authors":["Xi Shi","Qian Lou"],"tags":["Agentic RAG","Agentic Search","Multi-Agent","Evaluation"],"date":"2026-09-10","arxiv":"https://arxiv.org/abs/2609.10266","title":"KVShareArena: KV-Cache Reuse Across Contexts and Model Checkpoints","url":"https://arxiv.org/abs/2609.10266","source":"arxiv","topics":["Agentic RAG","Agentic Search","Multi-Agent","Evaluation"],"upvotes":0,"pdf":"https://arxiv.org/pdf/2609.10266.pdf","submittedDate":"2026-09-09","announceDate":"2026-09-10","abstract":"LLM serving systems already reuse KV caches, but only when the reused text sits at the very start of the prompt. Two growing workloads break this condition: a retrieval-augmented generation server assembles a different set of retrieved chunks for every query, and a multi-agent coordinator reads reports written by other agents. Reused inside a new prompt, a cache carries the wrong positions and never attended to the other sources. The cache may also have been written by a different checkpoint of the same model family, which changes the stored values. Repair methods for such caches have appeared in three separate communities, each measured on its own terms, and existing benchmarks test only exact-prefix reuse, where nothing is lost. KVShareArena benchmarks KV-cache reuse across prompt contexts and model checkpoints on retrieved chunks and agent reports. It scores every method by the fracti"},{"id":"arxiv:2609.10244","authors":["Eli Schwartz"],"tags":["LLM Training","VLM Training","Hallucination","Fine-tuning"],"date":"2026-09-10","arxiv":"https://arxiv.org/abs/2609.10244","title":"Two-Token Features and Small-Large Ensembles for VLM Hallucination Detection","url":"https://arxiv.org/abs/2609.10244","source":"arxiv","topics":["LLM Training","VLM Training","Hallucination","Fine-tuning"],"upvotes":0,"pdf":"https://arxiv.org/pdf/2609.10244.pdf","submittedDate":"2026-09-09","announceDate":"2026-09-10","abstract":"We present our system for the SHROOM-Visions 2026 shared task on character-level VLM hallucination detection. A small ($4$B-parameter) VLM is fine-tuned as a per-token classifier reading a two-token feature from its own hidden states, and is ensembled with a $\\sim$400B zero-shot VLM judge at prediction time. Both components see off-the-shelf OCR of any visible in-image text. We use synthetic hallucination data generated by the large model as a source of ensemble diversity, and use validation to select feature layer, training data and OCR grounding. Our official entry reaches mean Cor $0.487$ / Cor-lbl $0.387$ on the hidden test set, placing $6$th/$28$ (EN), $6$th/$21$ (FR), $8$th/$21$ (IT) and $7$th/$22$ (ZH) on the task's primary Cor-lbl metric."},{"id":"arxiv:2609.09764","authors":["Jianing Wang","Xintao Wang","Aili Chen","Jie Shi","Hongcheng Guo","Jun Gao","Wenxuan Zhao","Chengkun Lang","Yuanli Guo","Yanghua Xiao"],"tags":["Post-Training","Planning","Evaluation","RL for LLM"],"date":"2026-09-10","arxiv":"https://arxiv.org/abs/2609.09764","title":"SocialRL: Refining LLMs' Social Intelligence through Multi-turn Reinforcement Learning and Reward Design","url":"https://arxiv.org/abs/2609.09764","source":"arxiv","topics":["Post-Training","Planning","Evaluation","RL for LLM"],"upvotes":0,"pdf":"https://arxiv.org/pdf/2609.09764.pdf","submittedDate":"2026-09-09","announceDate":"2026-09-10","abstract":"Social intelligence enables agents to read social context, infer intent, and adapt over sustained dialogue. As language models become autonomous collaborators, it is central to building effective and trustworthy human-AI interaction. Existing reinforcement learning methods optimize single-turn utterances and sparse outcome rewards, producing short-sighted policies that struggle to manage goal-relationship tensions across multi-turn interactions. We propose SocialRL, a multi-turn reinforcement learning framework addressing both challenges. First, we apply multi-turn reinforcement learning using PPO that propagates delayed outcome rewards back to each turn, enabling long-horizon planning. Second, we design six process reward dimensions capturing the goal-relationship trade-off, including goal advancement, relational attunement, contextual coherence, etc. A reward model dynamically generate"},{"id":"arxiv:2609.09999","authors":["Xixian Liao","Maite Melero"],"tags":["Post-Training","LLM Training","Evaluation","Fine-tuning"],"date":"2026-09-10","arxiv":"https://arxiv.org/abs/2609.09999","title":"SalamandraTA at WMT 2026 Terminology Shared Task: Hard Examples Are Better Teachers","url":"https://arxiv.org/abs/2609.09999","source":"arxiv","topics":["Post-Training","LLM Training","Evaluation","Fine-tuning"],"upvotes":0,"pdf":"https://arxiv.org/pdf/2609.09999.pdf","submittedDate":"2026-09-09","announceDate":"2026-09-10","abstract":"Terminology-aware translation asks for more than a correct translation: the output must use the exact terms a glossary prescribes. The standard recipe, fine-tuning on glossary-annotated translation pairs, hides an inefficiency: for most examples the glossary prescribes exactly what the model would have produced anyway, so they teach nothing about following a glossary. We therefore keep only the examples where the model's own translation contradicts the glossary. In a controlled study at fixed data volume, this selection alone raises term accuracy from 78.7% to 89.9%. The filtered data, built by a two-way synthetic pipeline on open models, is part of the instruction-tuning mixture of our public release SalamandraTA-7b-instruct v3.0, which, used exactly as released and wrapped in a document-level inference pipeline, forms the BSC submission to the WMT26 Terminology Shared Task Track 1. At "},{"id":"arxiv:2609.10046","authors":["Quentin Signé","Mohand Boughanem","Jose Moreno","Thiziri Belkacem"],"tags":["Agentic RAG","Agentic Search","Hallucination","Evaluation"],"date":"2026-09-10","arxiv":"https://arxiv.org/abs/2609.10046","title":"Guaranteeing Faithful Evidence Extraction in Speculative Retrieval-Augmented Generation","url":"https://arxiv.org/abs/2609.10046","source":"arxiv","topics":["Agentic RAG","Agentic Search","Hallucination","Evaluation"],"upvotes":0,"pdf":"https://arxiv.org/pdf/2609.10046.pdf","submittedDate":"2026-09-09","announceDate":"2026-09-10","abstract":"Large Language Models (LLMs) are increasingly used as interfaces for information retrieval, but they remain prone to hallucinations and faithfulness errors, in which the generated answers diverge from the retrieved evidence. While Retrieval-Augmented Generation (RAG) and recent hybrid or semi-extractive approaches mitigate this issue, they do not guarantee that quoted or extracted spans are verbatim from the retrieved context. This limitation can have severe consequences in safety-critical domains, where answers must exactly match certified documentation. We introduce Constrained Hybrid Decoding (CHyD), a novel faithfulness-first paradigm for speculative RAG. While traditional speculative decoding is optimized for inference speed, CHyD repurposes this architecture to ensure faithful verbatim evidence extraction when the extraction mode is correctly triggered. Our approach enforces hard d"},{"id":"arxiv:2609.09163","authors":["James Schwoebel","Ingrida Semenec","Jenia Rousseva","Marcos Ortiz","Collin Overbay","Christopher Klaus","Anderson Edmond","Manish Bhatt","Rome Thorstenson","Jessica Tsai","Martin G. Frasch"],"tags":["Reasoning","Evaluation","Fine-tuning","World Model"],"date":"2026-09-10","arxiv":"https://arxiv.org/abs/2609.09163","title":"World-Time Compute with Verified Code World Models","url":"https://arxiv.org/abs/2609.09163","source":"arxiv","topics":["Reasoning","Evaluation","Fine-tuning","World Model"],"upvotes":0,"pdf":"https://arxiv.org/pdf/2609.09163.pdf","submittedDate":"2026-07-07","announceDate":"2026-09-10","abstract":"LLMs generalize across a domain only after seeing many real, labeled examples, which most domains lack. We study a way to manufacture it cheaply. When a domain's dynamics can be written as code, one template instantiates into many world models: executable, verifiable programs over symbolic state, each an inexhaustible source of exactly-labeled trajectories. Fine-tuning an LLM on trajectories through many such worlds, which we call world-time compute, a training-time analogue of test-time compute, lifts generalization to held-out worlds it never trained on (synthesized world families). Gains are largest where capability is scarcest: +29 points at 0.5B; the largest model's lift is within noise, consistent with saturation. Labels can be trusted because the worlds are verified code: synthesized-then-checked dynamics are exact over 20-step rollouts and answer 10x out-of-distribution probes ex"},{"id":"arxiv:2510.22115","authors":["Ling Team","Ang Li","Ben Liu","Binbin Hu","Bing Li","Bingwei Zeng","Borui Ye","Caizhi Tang","Changxin Tian","Chao Huang","Chao Zhang","Chen Qian","Chenchen Ju","Chenchen Li","Chengfu Tang","Chilin Fu","Chunshao Ren","Chunwei Wu","Cong Zhang","Cunyin Peng","Dafeng Xu","Daixin Wang","Dalong Zhang","Dingnan Jin","Dingyuan Zhu","Dongke Hu","Fangzheng Zhao","Feifan Wu","Feng Zhu","Gangshan Wang","Haitao Zhang","Hailin Zhao","Hanxiao Zhang","Hanzi Wang","Hao Qian","Haoyi Yu","Heng Zhang","Hongliang Zhang","Hongzhi Luan","Huirong Dong","Huizhong Li","Jia Li","Jia Liu","Jialong Zhu","Jian Sha","Jianping Wei","Jiaolong Yang","Jieyue Ma","Jiewei Wu","Jinjing Huang","Jingyun Tian","Jingyuan Zhang","Jinquan Sun","Juanhui Tu","Jun Liu","Jun Xu","Jun Zhou","Junjie Ou","Junpeng Fang","Kaihong Zhang","Kaiqin Hu","Ke Shi","Kun Tang","Kunlong Chen","Lanyin Mei","Lei Liang","Lei Xu","Libo Zhang","Lin Ju","Lin Yuan","Ling Zhong","Lintao Ma","Lu Liu","Lu Yu","Lun Cai","Meiqi Zhu","Mengying Li","Min Chen","Minghao Xue","Minghong Cai","Mingming Yin","Peijie Jiang","Peilong Zhao","Pingping Liu","Qian Zhao","Qing Cui","Qingxiang Huang","Qingyuan Yang","Quankun Yu","Shaowei Wei","Shijie Lian","Shoujian Zheng","Shun Song","Shungen Zhang","Shuo Zhang","Siyuan Li","Song Liu","Ting Guo","Tong Zhao","Wanli Gu","Weichang Wu","Weiguang Han","Wenjing Fang","Wubin Wang","Xiang Shu","Xiao Shi","Xiaoshun Lan","Xiaolu Zhang","Xiaqing Sun","Xin Zhao","Xingyu Lu","Xiong Xu","Xudong Wang","Xudong Wang","Xuemin Yang","Yajie Yang","Yang Xiang","Yanzhe Li","Yi Zhang","Yilong Wang","Yingxue Li","Yongzhen Guo","Yuzhuo Fu","Yuanyuan Wang","Yue Yang","Yue Yu","Yufeng Deng","Yun Zhang","Yunfei Yu","Yuqi Zhang","Yuxiao He","Zengke Gui","Zhaoxin Huan","Zhaoyang Wang","Zhibo Zhu","Zhihao Wang","Zhiqiang Zhang","Zhoufei Wang","Zihang Zeng","Ziqi Liu","Zitao Xuan","Zuoli Tang"],"tags":["Post-Training","LLM Training","Reasoning","Fine-tuning"],"date":"2026-09-10","arxiv":"https://arxiv.org/abs/2510.22115","title":"Every Activation Boosted: Scaling General Reasoner to 1 Trillion Open Language Foundation","url":"https://arxiv.org/abs/2510.22115","source":"arxiv","topics":["Post-Training","LLM Training","Reasoning","Fine-tuning"],"upvotes":0,"pdf":"https://arxiv.org/pdf/2510.22115.pdf","submittedDate":"2025-11-07","announceDate":"2026-09-10","abstract":"We introduce Ling 2.0, a series reasoning-oriented language foundation built upon the principle that every activation boosts reasoning capability. Designed to scale from tens of billions to one trillion parameters under a unified Mixture-of-Experts (MoE) paradigm, Ling 2.0 emphasizes high sparsity, cross-scale consistency, and efficiency guided by empirical scaling laws. The series includes three non-thinking (instruct) models - Ling-mini-2.0, Ling-flash-2.0, and Ling-1T - ranging from 16B to 1T total parameters and achieving up to 7-fold active-compute efficiency compared with dense counterparts. Ling 2.0 integrates coordinated innovations across model architecture, pre-training, post-training, and infrastructure: a high-sparsity MoE with MTP for efficient reasoning, reasoning-oriented data and mid-training CoT activation, reinforcement-based fine-tuning (DFT, Evo-CoT), and full-scale F"},{"id":"arxiv:2609.09895","authors":["Xinyu Chen","Adnan Mahmood","Mark Dras"],"tags":["Multi-Agent","Hallucination","Evaluation","Multimodal Agent"],"date":"2026-09-10","arxiv":"https://arxiv.org/abs/2609.09895","title":"Can We Trust Video Hallucination Detectors? VidHalLoc for Evaluating the Evaluators","url":"https://arxiv.org/abs/2609.09895","source":"arxiv","topics":["Multi-Agent","Hallucination","Evaluation","Multimodal Agent"],"upvotes":0,"pdf":"https://arxiv.org/pdf/2609.09895.pdf","submittedDate":"2026-09-09","announceDate":"2026-09-10","abstract":"Video-language models and video agents can produce hallucinations that conflict with spatiotemporal evidence. Existing benchmarks mainly evaluate model hallucinations, and heterogeneous mechanisms make detector reliability difficult to compare. We introduce VidHalLoc, a benchmark that evaluates hallucination detection methods under a unified diagnostic evaluation protocol using 2,000 adversarial hallucination samples across Video Question Answering and Video Captioning tasks, spanning Ontology and Dynamic hallucination categories. To construct VidHalLoc efficiently, we introduce VideoHALO, a Harness Engineering-informed multi-agent workflow that decomposes data construction into four executable stages supported by a memory system and a communication protocol. Evaluation of fifteen methods reveals that the four dedicated detectors peak at an Overall accuracy of only 34.63%, indicating lim"},{"id":"arxiv:2609.09417","authors":["Earl Ranario","Jared Smith","Lars Lundqvist","Urmil Jatin Chandarana"],"tags":["VLM Training","Reasoning","Hallucination","Evaluation"],"date":"2026-09-10","arxiv":"https://arxiv.org/abs/2609.09417","title":"Vision-language models know more about agriculture than they show and rubric-grounded verifications close the gap","url":"https://arxiv.org/abs/2609.09417","source":"arxiv","topics":["VLM Training","Reasoning","Hallucination","Evaluation"],"upvotes":0,"pdf":"https://arxiv.org/pdf/2609.09417.pdf","submittedDate":"2026-09-08","announceDate":"2026-09-10","abstract":"Vision-language models (VLMs) show promise for agricultural classification, but zero-shot performance on disease, pest, damage, quality, and species identification remains poor, and it is unclear whether this reflects weak visual features or a failure to connect them to domain knowledge. We build a benchmark of 116 datasets, 834 classes, and 8,324 images spanning these tasks to isolate where the gap arises. Linear probing shows VLM vision encoders already encode agricultural features nearly as separable as a self-supervised DINOv3 baseline, ruling out weak visual representations as the primary bottleneck. Conditioning each model on an oracle reference description (an upper bound on its parametric knowledge) closes most of the gap left by an unaided lower bound, showing VLMs already know more about agriculture than they show. To close this gap without an oracle description at inference ti"},{"id":"arxiv:2609.09203","authors":["Aayam Bansal","Keertan Balaji"],"tags":["Agent Safety","Reasoning","Evaluation"],"date":"2026-09-10","arxiv":"https://arxiv.org/abs/2609.09203","title":"OpenDiscoveryTrace: Process Traces for Evaluating AI Scientist Workflows","url":"https://arxiv.org/abs/2609.09203","source":"arxiv","topics":["Agent Safety","Reasoning","Evaluation"],"upvotes":0,"pdf":"https://arxiv.org/pdf/2609.09203.pdf","submittedDate":"2026-09-05","announceDate":"2026-09-10","abstract":"Existing benchmarks for autonomous AI scientists evaluate only final outputs---generated code, hypotheses, or papers---yet discard the reasoning process by which those outputs were obtained. This makes it impossible to audit scientific methodology, diagnose failure modes, or distinguish systematic reasoning from fortunate guessing. We present \\textbf{OpenDiscoveryTrace}, a public dataset of 558 complete AI scientific agent trajectories that captures how models reason, not just what they produce. Each trajectory records a structured 9-field-per-step trace---including thoughts, tool calls, observations, errors, revision triggers, and self-reported confidence---as models execute 124 scientific tasks spanning drug discovery, materials science, genomics, and scientific literature analysis. The dataset covers seven models: three frontier models (GPT-5.4, Claude Opus 4.6, and Gemini 3.1 Pro; 12"},{"id":"arxiv:2609.10016","authors":["Remco Hendriks"],"tags":["Reasoning","Evaluation","Fine-tuning"],"date":"2026-09-10","arxiv":"https://arxiv.org/abs/2609.10016","title":"MetroLLM-Bench: Evaluating Language Models as Transit Kiosk Runtimes","url":"https://arxiv.org/abs/2609.10016","source":"arxiv","topics":["Reasoning","Evaluation","Fine-tuning"],"upvotes":0,"pdf":"https://arxiv.org/pdf/2609.10016.pdf","submittedDate":"2026-09-09","announceDate":"2026-09-10","abstract":"We introduce MetroLLM-Bench, a 955-case benchmark for testing language models as the policy layer of a transit kiosk. It covers six real metro systems, ranging from 37 to 414 stations, and eleven categories that include routing, fare calculation, disruptions, accessibility, and adversarial input. In each case, the model must call structured tools and submit a machine-renderable terminal state containing an outcome, a per-ticket fare quote when applicable, and a kiosk action. Fourteen deterministic scoring components form Tier 1; eight semantic-quality components form Tier 2, six of which use a language-model judge. We report Tier 1 and the combined score of both tiers. A stratified 75/25 split reserves 717 cases for training-data generation and 238 for held-out evaluation. We evaluate twenty-six models from six vendors, of which twenty-three are ranked. On the held-out partition, a 4B Qw"},{"id":"arxiv:2609.10144","authors":["Ryan Lum","Yongfeng Zhang"],"tags":["Agentic Search","Agent Safety","Multi-Agent"],"date":"2026-09-10","arxiv":"https://arxiv.org/abs/2609.10144","title":"Kernel-Managed Shared Memory for System-Wide Personalization","url":"https://arxiv.org/abs/2609.10144","source":"arxiv","topics":["Agentic Search","Agent Safety","Multi-Agent"],"upvotes":0,"pdf":"https://arxiv.org/pdf/2609.10144.pdf","submittedDate":"2026-09-09","announceDate":"2026-09-10","abstract":"AI systems become more useful when they can adapt to the people using them, but in multi-agent systems, useful context learned by one agent often remains unavailable to others. We present kernel-managed shared memory, a system-level abstraction in which specialized agents write structured, tagged memories while the agent-system kernel, not individual agents, governs retrieval, privacy enforcement, and prompt injection. We implement and evaluate this design on AIOS and compare it against three alternatives across three assistant models (GPT-4o, Llama-3.1:8B, Qwen-2.5:7B) and 1,800 total trials. Against an unmanaged external memory backend (Mem0) using identical underlying storage, kernel-managed retrieval and injection improve personalization scores by 2.4-4.0 points on a 5-point scale (e.g., 1.05 to 4.69 profile usage on GPT-4o), with every comparison significant at p < 10^-18. Against s"},{"id":"arxiv:2609.10092","authors":["Yingqian Wu","Jingcong Liang","Siyuan Wang","Zhenfei Yin","Philip Torr","Junchi Yu","Zhongyu Wei"],"tags":["Agentic Search","Evaluation","Fine-tuning"],"date":"2026-09-10","arxiv":"https://arxiv.org/abs/2609.10092","title":"RAP: Research Attention Prediction Reveals Target-Conditioned Evidence Acquisition Biases","url":"https://arxiv.org/abs/2609.10092","source":"arxiv","topics":["Agentic Search","Evaluation","Fine-tuning"],"upvotes":0,"pdf":"https://arxiv.org/pdf/2609.10092.pdf","submittedDate":"2026-09-09","announceDate":"2026-09-10","abstract":"Large language models (LLMs) increasingly act as research agents, yet their ability to track shifts in research attention is difficult to evaluate because reviews and research ideas lack uniquely verifiable outcomes. We introduce Research Attention Prediction (RAP), a rolling benchmark covering 278 AI/ML fields and 1,390 episodes. At each cut-off, an LLM agent searches a temporally restricted arXiv corpus and predicts the next six months' paper shares across eight frozen research directions. Search generally helps, but all four diagnostic models perform worse than an exact-count exponentially weighted moving average (EWMA) baseline in compositional accuracy. We identify two linked bottlenecks. Under cumulative-history access, State carry-forward outperforms direct Forecast for all four diagnostic models; frozen-evidence replay links a shared component of this reversal to Forecast-oriente"},{"id":"arxiv:2609.09928","authors":["Yiqi Li","Xu Chen","Chen Ju","Jiangchao Yao","Zhaoyang Li","Jinsong Lan","Xiaoyong Zhu","Bo Zheng","Yu Wang"],"tags":["LLM Training","Reasoning","Alignment"],"date":"2026-09-10","arxiv":"https://arxiv.org/abs/2609.09928","title":"Structural Process Supervision for Latent Chain-of-Thought Reasoning","url":"https://arxiv.org/abs/2609.09928","source":"arxiv","topics":["LLM Training","Reasoning","Alignment"],"upvotes":0,"pdf":"https://arxiv.org/pdf/2609.09928.pdf","submittedDate":"2026-09-09","announceDate":"2026-09-10","abstract":"Latent reasoning approaches enhance token-level efficiency and robustness by replacing verbose, explicit chain-of-thought (CoT) tokens with compact continuous-space embeddings. However, existing methods lack direct process supervision over these latent embeddings, which often leads to representation collapse and uneven information distribution. To address this, we propose Prototype-Mediated Process Supervision (PMPS), which introduces learnable reasoning prototypes as semantic anchors to provide structural process-level supervision for latent reasoning. PMPS projects latent embeddings and explicit CoT embeddings into a shared prototype space, achieving many-to-many soft alignment between unequal-length representations through prototype assignment. Meanwhile, we introduce a Progressive Sequential Alignment (PSA) module to further guide training: positional priors initially encourage seque"},{"id":"arxiv:2609.09754","authors":["Yujin Zhou","Mingxuan Zheng","Chuxue Cao","Huang Yidan","Jiale Chen","Yike Guo","Sirui Han"],"tags":["Reasoning","Hallucination","Evaluation"],"date":"2026-09-10","arxiv":"https://arxiv.org/abs/2609.09754","title":"LexAgentHallu: A Hierarchical Benchmark for Profiling Hallucinations in Legal Agents","url":"https://arxiv.org/abs/2609.09754","source":"arxiv","topics":["Reasoning","Hallucination","Evaluation"],"upvotes":0,"pdf":"https://arxiv.org/pdf/2609.09754.pdf","submittedDate":"2026-09-09","announceDate":"2026-09-10","abstract":"As large language models are increasingly deployed as tool-augmented legal agents, they introduce agentic hallucinations where tool-call and reasoning errors cascade into fabricated holdings and miscited authority. However, existing legal benchmarks evaluate only single-turn QA with outcome-level metrics, while agentic hallucination benchmarks lack legal-specific diagnostic capability. Neither answers to what extent and how a legal agent hallucinates along its trajectory. To address these limitations, we introduce LexAgentHallu, a legal agentic hallucination benchmark designed to evaluate to what extent and how legal agents fail along multi-step trajectories. Built through a four-stage expert-in-the-loop pipeline, LexAgentHallu contains 3414 instances across 17 legal categories and 6 task types. Each instance is annotated under a dual-layer hallucination taxonomy of 7 high-level categori"},{"id":"arxiv:2609.09790","authors":["Hanjing Zhou","Mingze Yin","Ying Lian","Jun Ma","Chang-Yu Hsieh","Yanbing Zhou"],"tags":["VLM Training","Reasoning","Evaluation"],"date":"2026-09-10","arxiv":"https://arxiv.org/abs/2609.09790","title":"LogiScope-VQA: Benchmarking Vision-Language Models for Logistics Hazard Identification in Industrial Scenarios","url":"https://arxiv.org/abs/2609.09790","source":"arxiv","topics":["VLM Training","Reasoning","Evaluation"],"upvotes":0,"pdf":"https://arxiv.org/pdf/2609.09790.pdf","submittedDate":"2026-09-09","announceDate":"2026-09-10","abstract":"Large Multimodal Models (LMMs) large-scale deployment in industrial warehouse settings specifically necessitates that models exhibit human-expert-level hazard-oriented perception, understanding, and reasoning capabilities. However, the scarcity of real industrial data, tightly coupled to commercial terms, significantly hampers further advancement. To bridge this gap, we curate LogiScope-VQA to investigate the practical applicability of mainstream LMMs in real-world logistics operations. LogiScope-VQA comprises 2,476 images and 2,918 videos primarily sourced from real-world logistics parks, along with 10,274 VQAs meticulously curated and validated by human annotators. Grounded in 18 core objects and 20 risk types, we devise 39 subtasks aligned with three principal themes: industrial element perception, warehouse knowledge understanding, and potential risk reasoning. Furthermore, we incorp"}],"archive":[],"latestPath":"data/latest.json"};
